      var fy = gridY + f * fs;
      svg.push('<line x1="' + gridX + '" y1="' + fy + '" x2="' + (gridX + gridW) + '" y2="' + fy + '" stroke="' + ink + '" stroke-opacity="0.22" stroke-width="1.2"/>');
